package org.beckenburg.editor;

import java.io.*;
import java.nio.*;
import java.nio.file.*;
import java.util.*;
import org.beckenburg.editor.EditorMeshPipeline.*;

/** Persisted local frames, affine conjugation and actual native/OBJ/GLB readbacks. */
public final class EditorLocalFrameTest {
    private static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    private static void near(double a,double b){check(Math.abs(a-b)<1e-8,"Local result "+a+" != "+b);}
    private interface Action{void run()throws Exception;}
    private static void refuse(Action a)throws Exception{try{a.run();throw new AssertionError("Expected local frame refusal");}catch(IOException|IllegalArgumentException|IllegalStateException expected){}}
    private static Mesh fixture(){var normal=new Normal(0,0,2);return new Mesh("local.obj",List.of(new Triangle("panel",new Vertex(1,0,0,0,0,normal),new Vertex(2,0,0,1,0,normal),new Vertex(1,1,0,0,1,normal))),0);}
    private static void points(EditorTopologyProject p,Mesh original){var frame=p.frame("panel");var source=List.of(original.triangles().get(0).a(),original.triangles().get(0).b(),original.triangles().get(0).c());for(int i=0;i<3;i++){var v=p.snapshot().vertices().get(i);var old=source.get(i);near(v.x(),frame.direction(old.x(),old.y(),old.z(),0)+frame.ox());near(v.y(),frame.direction(old.x(),old.y(),old.z(),1)+frame.oy());near(v.z(),frame.direction(old.x(),old.y(),old.z(),2)+frame.oz());}}
    public static void main(String[] args)throws Exception{
        Path root=Files.createTempDirectory("native-local-frame-");try{
            double[] zero=EditorMeshFrame.IDENTITY.values();zero[1]=-0.0;zero[3]=-0.0;check(EditorMeshFrame.fromValues(zero).equals(EditorMeshFrame.IDENTITY),"Native frame signed zeros canonicalize before native/JSON roundtrip");
            var original=fixture();var p=EditorTopologyProject.fromMesh(original,"0".repeat(64),root.resolve("local.btop"));var initial=p.snapshot();check(initial.frames().isEmpty()&&p.frame("panel").equals(EditorMeshFrame.IDENTITY),"Old native geometry defaults to original identity editing frame");var ids=Set.of(0L,1L,2L);var history=new EditorHistory<>(p,20);
            var rotation=p.previewTransform(ids,EditorTopologyProject.Transform.ROTATE,2,90,true);history.execute(()->p.applyPreview(rotation));points(p,original);near(p.frame("panel").axis(0).y(),1);var rotated=p.snapshot();
            var local=p.previewLocalTransform(ids,EditorTopologyProject.Transform.SCALE_AXIS,0,2,true);check(p.snapshot()==rotated,"Local preview never mutates authoritative geometry/frame");near(local.snapshot().vertices().get(0).x(),0);near(local.snapshot().vertices().get(0).y(),2);history.execute(()->p.applyPreview(local));points(p,original);var scaled=p.snapshot();check(history.undo()&&p.snapshot().equals(rotated)&&history.redo()&&p.snapshot().equals(scaled),"Geometry and frames share one exact history entry");
            var rotateLocal=p.previewLocalTransform(ids,EditorTopologyProject.Transform.ROTATE,2,90,true);history.execute(()->p.applyPreview(rotateLocal));points(p,original);history.execute(()->p.translateVertices(ids,3,4,5));points(p,original);near(p.frame("panel").ox(),3);near(p.frame("panel").oy(),4);near(p.frame("panel").oz(),5);
            var complete=p.snapshot();p.save();byte[] bytes=Files.readAllBytes(p.documentPath());check(ByteBuffer.wrap(bytes).getInt(4)==5&&EditorTopologyProject.open(p.documentPath()).snapshot().equals(complete),"Native v5 deterministic exact frame/geometry fresh reopen");check(Arrays.equals(bytes,p.snapshotBytes()),"Native frame serialization deterministic");try{p.snapshot().frames().clear();throw new AssertionError("Mutable native frame table");}catch(UnsupportedOperationException expected){}
            var obj=new ByteArrayOutputStream();EditorObjWriter.write(complete,obj);EditorObjWriter.validate(complete,obj.toByteArray());var imported=EditorMeshPipeline.read("copy.obj",obj.toByteArray());check(imported.frames().equals(complete.frames()),"Actual OBJ native comments retain exact local frame");var bundle=new ByteArrayOutputStream();EditorObjBundle.write(complete,bundle);EditorObjBundle.validate(complete,bundle.toByteArray());check(EditorObjBundle.read("copy.obj.zip",bundle.toByteArray()).frames().equals(complete.frames()),"Material bundle views retain frame metadata without parallel geometry");
            byte[] glb=EditorGlbWriter.encode(p.mesh());EditorGlbWriter.validate(p.mesh(),glb);var decoded=EditorGlbReader.read(glb);check(decoded.frames().get("glb_node_0").equals(p.frame("panel")),"Actual shared GLB decoder observes the same baked editing frame");var reopened=EditorTopologyProject.fromGlb("copy.glb",glb,root.resolve("copy.btop"));check(reopened.frame("glb_node_0").equals(p.frame("panel")),"GLB fresh import retains local axes/pivot, not only world triangles");
            var frame=p.frame("panel");var v=p.snapshot().vertices().get(0);p.moveVertex(v.id(),v.x()+.125,v.y(),v.z());check(p.frame("panel").equals(frame),"Partial component deformation does not replace its object-local frame");p.restore(complete);var stale=p.previewLocalTransform(ids,EditorTopologyProject.Transform.ROTATE,0,15,false);p.translateVertices(ids,.1,0,0);refuse(()->p.applyPreview(stale));p.restore(complete);long revision=p.revision();refuse(()->p.previewLocalTransform(ids,EditorTopologyProject.Transform.ROTATE,0,360,false));refuse(()->p.previewLocalTransform(ids,EditorTopologyProject.Transform.SCALE_AXIS,0,1,false));refuse(()->p.previewLocalTransform(Set.of(999L),EditorTopologyProject.Transform.ROTATE,0,15,false));check(p.snapshot()==complete&&p.revision()==revision,"Local invalid/stale controls preserve native state/epoch");
            var normal=new Normal(1,1,1);var tilted=new Mesh("affine",List.of(new Triangle("panel",new Vertex(0,0,0,0,0,normal),new Vertex(1,-1,0,1,0,normal),new Vertex(1,0,-1,0,1,normal))),0);var affine=EditorTopologyProject.fromMesh(tilted,"2".repeat(64),root.resolve("affine.btop"));affine.applyPreview(affine.previewTransform(ids,EditorTopologyProject.Transform.SCALE_AXIS,0,2,true));affine.applyPreview(affine.previewLocalTransform(ids,EditorTopologyProject.Transform.ROTATE,2,90,true));var transformed=affine.snapshot().faces().get(0).a().normal();near(transformed.x(),-1d/3);near(transformed.y(),2d/3);near(transformed.z(),2d/3);
            var shear=EditorTopologyProject.fromMesh(tilted,"3".repeat(64),root.resolve("shear.btop"));shear.applyPreview(shear.previewTransform(ids,EditorTopologyProject.Transform.ROTATE,2,45,true));shear.applyPreview(shear.previewTransform(ids,EditorTopologyProject.Transform.SCALE_AXIS,0,2,true));var target=shear.frame("panel").multiply(EditorMeshFrame.operation(EditorTopologyProject.Transform.ROTATE,0,30));shear.applyPreview(shear.previewLocalTransform(ids,EditorTopologyProject.Transform.ROTATE,0,30,true));double[] wantedFrame=target.values(),actualFrame=shear.frame("panel").values();for(int i=0;i<12;i++)near(wantedFrame[i],actualFrame[i]);var faceNormal=EditorMeshNormals.face(shear.mesh().triangles().get(0));var authored=EditorMeshNormals.unit(shear.snapshot().faces().get(0).a().normal());near(authored.x(),faceNormal.x());near(authored.y(),faceNormal.y());near(authored.z(),faceNormal.z());EditorGlbWriter.validate(shear.mesh(),EditorGlbWriter.encode(shear.mesh()));
            var source=EditorTopologyProject.fromGlb("assembly.glb",EditorGlbAuthoringTest.fixture(),root.resolve("source.btop"));var sourceBefore=source.snapshot();var sourceFrame=EditorMeshFrame.matrix(sourceBefore.glbSource().world(1));check(source.frame("glb_node_1").equals(sourceFrame),"GLB local frame is actual ancestor/node matrix including nonuniform scale");var selected=new HashSet<Long>();for(var vertex:sourceBefore.vertices())if(vertex.part().equals("glb_node_1"))selected.add(vertex.id());source.applyPreview(source.previewLocalTransform(selected,EditorTopologyProject.Transform.ROTATE,2,30,true));byte[] edited=EditorGlbWriter.encode(source.mesh());EditorGlbWriter.validate(source.mesh(),edited);var after=EditorGlbReader.read(edited);var oldNodes=EditorGlbReader.arr(sourceBefore.glbSource().root().get("nodes"));var newNodes=EditorGlbReader.arr(after.root().get("nodes"));for(int i=0;i<oldNodes.size();i++)for(var entry:EditorGlbReader.obj(oldNodes.get(i)).entrySet())if(!entry.getKey().equals("mesh"))check(entry.getValue().equals(EditorGlbReader.obj(newNodes.get(i)).get(entry.getKey())),"Original source pivots/TRS/hierarchy properties remain exact");check(after.frames().get("glb_node_1").equals(source.frame("glb_node_1")),"Edited source instance frame retained separately from original immutable source pivots");source.save();check(EditorTopologyProject.open(source.documentPath()).snapshot().equals(source.snapshot()),"Source-backed native v5 source/frame save roundtrip");
            var allSource=source.snapshot().vertices().stream().map(EditorTopologyProject.Vertex::id).toList();var sourcePositions=source.snapshot().vertices();var sourceFrames=source.frames(sourcePositions.stream().map(EditorTopologyProject.Vertex::part).distinct().toList());source.translateLocalVertices(allSource,0,.25);for(int i=0;i<sourcePositions.size();i++){var old=sourcePositions.get(i);var now=source.snapshot().vertices().get(i);var direction=sourceFrames.get(old.part()).vector(0);near(now.x(),old.x()+direction.x()*.25);near(now.y(),old.y()+direction.y()*.25);near(now.z(),old.z()+direction.z()*.25);}EditorGlbWriter.validate(source.mesh(),EditorGlbWriter.encode(source.mesh()));
            source.save();check(EditorTopologyProject.open(source.documentPath()).snapshot().equals(source.snapshot()),"Multi-part local movement persists both actual frames");
            var invalid=bytes.clone();ByteBuffer.wrap(invalid).putDouble(invalid.length-96,Double.NaN);refuse(()->EditorTopologyProject.decode(invalid));
            var rootJson=EditorGlbReader.obj(EditorGlbJson.read(EditorGlbJson.write(decoded.root())));var node=EditorGlbReader.obj(EditorGlbReader.arr(rootJson.get("nodes")).get(0));var extensions=EditorGlbReader.obj(node.get("extensions"));var oldOrder=extensions.put("BECK_native_order",Map.of("version",1,"triangles",List.of(1)));refuse(()->EditorGlbReader.read(EditorGlbDocumentWriter.container(rootJson,decoded.binary())));extensions.put("BECK_native_order",oldOrder);extensions.put("BECK_editor_frame",Map.of("version",2,"bakedWorldGeometry",true,"matrix",Arrays.stream(frame.values()).boxed().toList()));refuse(()->EditorGlbReader.read(EditorGlbDocumentWriter.container(rootJson,decoded.binary())));
            var sparse=new Mesh("sparse",original.triangles(),0,List.of(0L,1L,2L),List.of(),null,List.of(7L));EditorGlbWriter.validate(sparse,EditorGlbWriter.encode(sparse));
            var future=bytes.clone();ByteBuffer.wrap(future).putInt(4,7);refuse(()->EditorTopologyProject.decode(future));refuse(()->EditorMeshPipeline.read("invalid.obj",("# beck_native_frame_v2 panel 1\n"+new String(obj.toByteArray(),java.nio.charset.StandardCharsets.UTF_8)).getBytes(java.nio.charset.StandardCharsets.UTF_8)));
            if(args.length>0&&!args[0].equals("--stress")){Path output=Path.of(args[0]);Files.createDirectories(output);Files.write(output.resolve("local.glb"),glb);Files.write(output.resolve("local.obj"),obj.toByteArray());Files.write(output.resolve("local.btop"),bytes);Files.write(output.resolve("source-local.glb"),EditorGlbWriter.encode(source.mesh()));Files.write(output.resolve("source-local.btop"),source.snapshotBytes());}
            if(args.length>0&&args[0].equals("--stress")){
                var vertices=new ArrayList<EditorTopologyProject.Vertex>();var faces=new ArrayList<EditorTopologyProject.Face>();var maximumNormal=new Normal(1,1,1);for(int i=0;i<EditorMeshPipeline.MAX_TRIANGLES;i++){long id=(long)i*3;double x=i*4;vertices.add(new EditorTopologyProject.Vertex(id,"maximum",x,0,0));vertices.add(new EditorTopologyProject.Vertex(id+1,"maximum",x+1,1,0));vertices.add(new EditorTopologyProject.Vertex(id+2,"maximum",x,0,1));faces.add(new EditorTopologyProject.Face(i,"maximum",new EditorTopologyProject.Corner(id,0,0,maximumNormal),new EditorTopologyProject.Corner(id+1,1,0,maximumNormal),new EditorTopologyProject.Corner(id+2,0,1,maximumNormal)));}
                p.restore(new EditorTopologyProject.State(initial.sceneId(),initial.sourceFingerprint(),"maximum",0,vertices,faces));var selectedIds=new HashSet<Long>();for(var vertex:vertices)selectedIds.add(vertex.id());var candidate=p.previewLocalTransform(selectedIds,EditorTopologyProject.Transform.ROTATE,0,15,false);check(candidate.snapshot().vertices().size()==360000&&candidate.snapshot().faces().size()==120000&&candidate.snapshot().frames().containsKey("maximum"),"Maximum normal-bearing local transform and frame under256MiB");
            }
            System.out.println("PASS native local frames: actual affine source axes/pivots, per-part local conjugation, atomic geometry/frame history, v1-v5 compatibility, deterministic native/OBJ/bundle/GLB roundtrip and source hierarchy preservation");
        }finally{try(var paths=Files.walk(root)){for(var path:paths.sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(path);}}
    }
}
